def modular_sum(nums, m, sum):
    """
    Determine if there is a subset with sum divisible by m.

    Args:
    nums (list of int): The list of integers to search through.
    m (int): The divisor to check divisibility against.
    sum (int): The target sum for the subset.

    Returns:
    bool: True if there exists a subset with sum divisible by m, False otherwise.
    """
    def subset_sum(target, current_sum, index):
        if current_sum == target:
            return True
        if current_sum > target or index >= len(nums):
            return False
        return subset_sum(target, current_sum + nums[index], index + 1) or subset_sum(target, current_sum, index + 1)

